// Stub types for the wasm-pack output, so `tsc --noEmit` runs without a prior `build:wasm` (ledger ARCH-22, W19).
// Written 2026-11-04; mirrors the surface src/ uses from pkg/command_search_wasm.d.ts as generated by wasm-bindgen 0.2.130.
//
// This is a PATTERN ambient module. TypeScript consults pattern ambient modules only after normal file
// resolution of the import fails: with pkg/ present the generated pkg/command_search_wasm.d.ts wins,
// without it this stub applies. src/pkg-stub.test.ts fails if the generated surface drifts from this file.
declare module '*/pkg/command_search_wasm.js' {
  export class WasmSearchEngine {
    free(): void;
    [Symbol.dispose](): void;
    clear(): void;
    index_items(items: string): void;
    constructor();
    // biome-ignore lint/suspicious/noExplicitAny: mirrors the wasm-bindgen output, which declares any
    search(query: string, max_results: number): any;
  }

  export type InitInput = RequestInfo | URL | Response | BufferSource | WebAssembly.Module;

  export interface InitOutput {
    readonly memory: WebAssembly.Memory;
  }

  export type SyncInitInput = BufferSource | WebAssembly.Module;

  export function initSync(module: { module: SyncInitInput } | SyncInitInput): InitOutput;

  export default function __wbg_init(
    module_or_path?:
      | { module_or_path: InitInput | Promise<InitInput> }
      | InitInput
      | Promise<InitInput>,
  ): Promise<InitOutput>;
}
